@Nullable private static Metadata parseIlst(ParsableByteArray ilst, int limit) {
  ilst.skipBytes(Atom.HEADER_SIZE);
  ArrayList<Metadata.Entry> entries = new ArrayList<>();
  while (ilst.getPosition() < limit) {
    try {
      @Nullable Metadata.Entry entry = MetadataUtil.parseIlstElement(ilst);
      if (entry != null) {
        entries.add(entry);
      }
    } catch (IndexOutOfBoundsException | ArrayStoreException | NullPointerException e) {
      // Log the exception and continue parsing the next entry
      System.err.println("Error parsing metadata entry: " + e.getMessage());
    }
  }
  return entries.isEmpty() ? null : new Metadata(entries);
}
